"use client";

import React, { useState, useMemo, useEffect, useCallback, useRef } from "react";
import Image from "next/image";
import Link from "next/link";
import Navbar from "@/components/Navbar";
import { useShift } from "@/app/context/ShiftContext";
import { useAuth } from "@/app/context/AuthContext";
import { supabase } from "@/lib/supabaseClient";
import { processSaleInDB, POSCartItem } from "@/services/inventoryService";
import {
  Scan,
  Trash2,
  Minus,
  Plus,
  X,
  Banknote,
  CreditCard,
  Building2,
  Printer,
  Package,
  Search,
  Lock,
  Loader2,
  AlertTriangle,
  ArrowRight,
  CheckCircle2,
} from "lucide-react";

interface DBBranchRelation {
  id: string;
  name: string;
}

interface DBBranchInventory {
  stock: number | null;
  branches: DBBranchRelation | null;
}

interface DBProductPOS {
  id: string;
  sku: string;
  barcode: string | null;
  name: string;
  brand: string;
  category: string;
  price: number;
  image_url: string | null;
  branch_inventory: DBBranchInventory[] | null;
}

export interface POSProduct {
  id: string;
  sku: string;
  barcode?: string;
  name: string;
  brand: string;
  category: string;
  price: number;
  stock: number;
  image?: string;
}

const CATEGORIES = ["All", "Ortho", "Endo", "Resins", "Instruments", "Disposables"];

export default function PosPage() {
  const { isShiftOpen, cashierName } = useShift();
  const { user } = useAuth();

  const currentBranch = user?.branch || "Santa Ana";

  const [products, setProducts] = useState<POSProduct[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState("All");
  const [searchQuery, setSearchQuery] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<"cash" | "card" | "transfer">("cash");
  const [cart, setCart] = useState<POSCartItem[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [ticketSuccess, setTicketSuccess] = useState<string | null>(null);

  const scanInputRef = useRef<HTMLInputElement>(null);

  // Carga reactiva de productos reales filtrados por la sucursal actual
  const loadBranchProducts = useCallback(async () => {
    try {
      setIsLoading(true);

      const { data, error } = await supabase
        .from("products")
        .select(`
          id,
          sku,
          barcode,
          name,
          brand,
          category,
          price,
          image_url,
          branch_inventory (
            stock,
            branches (
              id,
              name
            )
          )
        `)
        .order("name", { ascending: true });

      if (error) throw error;

      const formatted: POSProduct[] = ((data ?? []) as unknown as DBProductPOS[]).map((p) => {
        const invList = p.branch_inventory ?? [];
        const branchMatch = invList.find(
          (b) => b.branches?.name?.toLowerCase() === currentBranch.toLowerCase()
        );

        return {
          id: p.id,
          sku: p.sku,
          barcode: p.barcode ?? undefined,
          name: p.name,
          brand: p.brand,
          category: p.category,
          price: Number(p.price),
          stock: branchMatch?.stock ?? 0,
          image: p.image_url ?? undefined,
        };
      });

      setProducts(formatted);
    } catch (err) {
      console.error("Error al cargar productos del POS:", err);
    } finally {
      setIsLoading(false);
    }
  }, [currentBranch]);

  useEffect(() => {
    loadBranchProducts();
  }, [loadBranchProducts]);

  // Filtrado reactivo por categoría y buscador/lector de código de barras
  const filteredProducts = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return products.filter((p) => {
      const matchCat = activeCategory === "All" || p.category.toLowerCase() === activeCategory.toLowerCase();
      const matchQuery =
        !q ||
        p.name.toLowerCase().includes(q) ||
        p.brand.toLowerCase().includes(q) ||
        p.sku.toLowerCase().includes(q) ||
        (p.barcode && p.barcode.toLowerCase().includes(q));

      return matchCat && matchQuery;
    });
  }, [products, activeCategory, searchQuery]);

  // Agregar al carrito
  const addToCart = (product: POSProduct) => {
    if (!isShiftOpen) return;
    if (product.stock <= 0) return;

    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) return prev; // Límite de stock físico
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [
        ...prev,
        {
          id: product.id,
          sku: product.sku,
          name: product.name,
          brand: product.brand,
          price: product.price,
          quantity: 1,
          stock: product.stock,
        },
      ];
    });

    setSearchQuery("");
  };

  // Detección automática por código de barras (Enter)
  const handleBarcodeKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" && searchQuery.trim()) {
      e.preventDefault();
      const code = searchQuery.trim().toLowerCase();
      const match = products.find(
        (p) => p.sku.toLowerCase() === code || (p.barcode && p.barcode.toLowerCase() === code)
      );

      if (match) {
        addToCart(match);
      }
    }
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart((prev) =>
      prev
        .map((item) => {
          if (item.id !== id) return item;
          const nextQty = item.quantity + delta;
          if (nextQty > item.stock) return item;
          return { ...item, quantity: nextQty };
        })
        .filter((item) => item.quantity > 0)
    );
  };

  const removeItem = (id: string) => {
    setCart((prev) => prev.filter((item) => item.id !== id));
  };

  const clearCart = () => setCart([]);

  // Cálculos monetarios
  const subtotal = useMemo(
    () => cart.reduce((acc, curr) => acc + curr.price * curr.quantity, 0),
    [cart]
  );
  const tax = Number((subtotal * 0.13).toFixed(2));
  const total = Number((subtotal + tax).toFixed(2));

  // Procesar venta en Supabase
  const handleCheckout = async () => {
    if (cart.length === 0 || !isShiftOpen) return;

    try {
      setIsProcessing(true);
      const result = await processSaleInDB({
        branchName: currentBranch,
        cashierId: user?.id,
        cashierName: cashierName || user?.name || "Cajero",
        paymentMethod,
        items: cart,
        subtotal,
        tax,
        total,
      });

      setTicketSuccess(result.ticketNumber);
      clearCart();
      await loadBranchProducts(); // Refrescar stock en vivo tras la venta
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Error al procesar la venta";
      alert(msg);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-slate-700 flex flex-col font-sans select-none">
      <Navbar />

      {/* Banner si el turno está cerrado */}
      {!isShiftOpen && (
        <div className="bg-amber-50 border-b border-amber-200 px-6 py-2.5 flex items-center justify-between text-amber-800 text-xs font-semibold">
          <div className="flex items-center gap-2">
            <Lock className="w-4 h-4 text-amber-600 shrink-0" />
            <span>Turno cerrado: dirígete a Caja para registrar fondo inicial y cobrar.</span>
          </div>
          <Link
            href="/caja"
            className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold transition-colors shadow-2xs"
          >
            <span>Ir a Caja</span>
            <ArrowRight className="w-3.5 h-3.5" />
          </Link>
        </div>
      )}

      {/* Notificación de venta completada */}
      {ticketSuccess && (
        <div className="bg-emerald-600 text-white px-6 py-2.5 flex items-center justify-between text-xs font-bold shadow-md animate-in slide-in-from-top-2">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4" />
            <span>¡Venta completada con éxito! Comprobante emitido: <strong>{ticketSuccess}</strong></span>
          </div>
          <button
            type="button"
            onClick={() => setTicketSuccess(null)}
            className="p-1 hover:bg-emerald-700 rounded-lg transition-colors cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      <div className="flex-1 flex overflow-hidden">
        {/* COLUMNA IZQUIERDA: Catálogo y Buscador */}
        <div className="flex-1 p-6 overflow-y-auto space-y-5">
          {/* Barra de escáner / Búsqueda */}
          <div className="border border-sky-400 rounded-xl px-4 py-2.5 bg-white flex items-center gap-3 shadow-2xs focus-within:ring-2 focus-within:ring-sky-100 transition-all">
            <Scan className="w-5 h-5 text-sky-500 shrink-0" />
            <input
              ref={scanInputRef}
              type="text"
              autoFocus
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={handleBarcodeKeyDown}
              placeholder="Escanear código de barras o buscar por SKU / Nombre..."
              className="w-full bg-transparent text-xs font-medium text-slate-800 placeholder-slate-400 focus:outline-none"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery("")}
                className="text-slate-400 hover:text-slate-600"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>

          {/* Filtros de categorías */}
          <div className="flex items-center gap-2 overflow-x-auto pb-1">
            {CATEGORIES.map((cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-1.5 rounded-xl text-xs font-bold border transition-colors cursor-pointer shrink-0 ${
                  activeCategory === cat
                    ? "bg-sky-600 text-white border-sky-600 shadow-2xs"
                    : "bg-white text-slate-600 border-slate-200 hover:bg-slate-50"
                }`}
              >
                {cat === "All" ? "Todos" : cat}
              </button>
            ))}
          </div>

          {/* Cuadrícula de productos */}
          {isLoading ? (
            <div className="py-24 flex flex-col items-center justify-center text-slate-400 gap-2.5">
              <Loader2 className="w-7 h-7 animate-spin text-sky-600" />
              <span className="text-xs font-medium">Cargando inventario de {currentBranch}...</span>
            </div>
          ) : filteredProducts.length > 0 ? (
            <div className="grid grid-cols-4 gap-4">
              {filteredProducts.map((p) => {
                const isOutOfStock = p.stock <= 0;

                return (
                  <div
                    key={p.id}
                    onClick={() => !isOutOfStock && addToCart(p)}
                    className={`bg-white border rounded-2xl p-3.5 flex flex-col justify-between transition-all select-none relative ${
                      isOutOfStock
                        ? "border-slate-200 opacity-60 cursor-not-allowed"
                        : "border-slate-200/80 hover:border-sky-400 hover:shadow-md cursor-pointer active:scale-[0.98]"
                    }`}
                  >
                    {/* Visualizador de imagen */}
                    <div className="w-full h-28 bg-slate-50 rounded-xl mb-3 flex items-center justify-center overflow-hidden relative border border-slate-100">
                      {p.image ? (
                        <Image
                          src={p.image}
                          alt={p.name}
                          fill
                          unoptimized
                          className="object-contain p-2"
                        />
                      ) : (
                        <Package className="w-8 h-8 text-slate-300 stroke-[1.5]" />
                      )}
                    </div>

                    <div>
                      <div className="flex items-start justify-between gap-1 mb-1">
                        <p className="text-xs font-bold text-slate-800 line-clamp-2 leading-tight">
                          {p.name}
                        </p>
                        <span
                          className={`text-[10px] font-mono font-bold px-1.5 py-0.5 rounded-md shrink-0 ${
                            isOutOfStock
                              ? "bg-rose-50 text-rose-600 border border-rose-100"
                              : p.stock <= 5
                              ? "bg-amber-50 text-amber-600 border border-amber-200"
                              : "bg-emerald-50 text-emerald-700 border border-emerald-200"
                          }`}
                        >
                          {isOutOfStock ? "Agotado" : p.stock}
                        </span>
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium mb-3">{p.brand}</p>
                    </div>

                    <div className="flex items-center justify-between pt-2 border-t border-slate-100">
                      <span className="font-mono text-sm font-extrabold text-slate-900">
                        ${p.price.toFixed(2)}
                      </span>
                      <button
                        type="button"
                        disabled={isOutOfStock || !isShiftOpen}
                        className="px-2 py-1 bg-sky-50 text-sky-700 font-bold text-[11px] rounded-lg hover:bg-sky-100 transition-colors disabled:opacity-50 cursor-pointer"
                      >
                        + Agregar
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="py-20 text-center text-slate-400 text-xs">
              No se encontraron productos disponibles en el catálogo de {currentBranch}.
            </div>
          )}
        </div>

        {/* COLUMNA DERECHA: Orden Actual y Cobro */}
        <div className="w-96 bg-white border-l border-slate-200 flex flex-col justify-between shrink-0 shadow-sm">
          {/* Cabecera del Carrito */}
          <div className="p-4 border-b border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-sm font-bold text-slate-800">Orden Actual</span>
              <span className="text-xs font-mono font-bold text-sky-600 bg-sky-50 px-2 py-0.5 rounded-md">
                #{cart.length}
              </span>
            </div>
            {cart.length > 0 && (
              <button
                type="button"
                onClick={clearCart}
                className="text-slate-400 hover:text-rose-600 transition-colors p-1"
                title="Vaciar carrito"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
          </div>

          {/* Lista de ítems en orden */}
          <div className="flex-1 p-4 overflow-y-auto divide-y divide-slate-100 space-y-3">
            {cart.length > 0 ? (
              cart.map((item) => (
                <div key={item.id} className="pt-3 first:pt-0 flex items-center justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold text-slate-800 truncate">{item.name}</p>
                    <p className="text-[10px] text-slate-400">{item.brand} • ${item.price.toFixed(2)} c/u</p>
                  </div>

                  <div className="flex items-center gap-2 shrink-0">
                    <div className="flex items-center border border-slate-200 rounded-lg overflow-hidden bg-slate-50">
                      <button
                        type="button"
                        onClick={() => updateQuantity(item.id, -1)}
                        className="p-1 hover:bg-slate-200 text-slate-600 transition-colors cursor-pointer"
                      >
                        <Minus className="w-3 h-3" />
                      </button>
                      <span className="px-2 font-mono text-xs font-bold text-slate-800">
                        {item.quantity}
                      </span>
                      <button
                        type="button"
                        onClick={() => updateQuantity(item.id, 1)}
                        disabled={item.quantity >= item.stock}
                        className="p-1 hover:bg-slate-200 text-slate-600 transition-colors cursor-pointer disabled:opacity-40"
                      >
                        <Plus className="w-3 h-3" />
                      </button>
                    </div>

                    <span className="font-mono text-xs font-bold text-slate-800 w-16 text-right">
                      ${(item.price * item.quantity).toFixed(2)}
                    </span>

                    <button
                      type="button"
                      onClick={() => removeItem(item.id)}
                      className="p-1 text-slate-300 hover:text-rose-600 transition-colors cursor-pointer"
                    >
                      <X className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <div className="py-24 text-center text-slate-400 space-y-2">
                <Package className="w-8 h-8 text-slate-300 mx-auto" />
                <p className="text-xs font-semibold text-slate-500">No hay productos en la orden actual</p>
                <p className="text-[11px] text-slate-400 max-w-[200px] mx-auto">
                  Selecciona un producto del catálogo o escanea un código de barras.
                </p>
              </div>
            )}
          </div>

          {/* Liquidación y Métodos de Pago */}
          <div className="p-4 border-t border-slate-100 bg-slate-50/50 space-y-3">
            <div className="space-y-1.5 text-xs text-slate-600">
              <div className="flex justify-between">
                <span>Subtotal</span>
                <span className="font-mono font-medium">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between">
                <span>IVA (13%)</span>
                <span className="font-mono font-medium">${tax.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-base font-black text-slate-900 pt-2 border-t border-slate-200">
                <span>Total</span>
                <span className="font-mono text-sky-600">${total.toFixed(2)}</span>
              </div>
            </div>

            {/* Selección de Pago */}
            <div className="grid grid-cols-3 gap-1.5 pt-1">
              <button
                type="button"
                onClick={() => setPaymentMethod("cash")}
                className={`py-2 px-1 rounded-xl border text-[11px] font-bold flex flex-col items-center gap-1 transition-all cursor-pointer ${
                  paymentMethod === "cash"
                    ? "bg-sky-50 border-sky-400 text-sky-700 shadow-2xs"
                    : "bg-white border-slate-200 text-slate-600 hover:bg-slate-50"
                }`}
              >
                <Banknote className="w-4 h-4 text-sky-600" />
                <span>Efectivo</span>
              </button>

              <button
                type="button"
                onClick={() => setPaymentMethod("card")}
                className={`py-2 px-1 rounded-xl border text-[11px] font-bold flex flex-col items-center gap-1 transition-all cursor-pointer ${
                  paymentMethod === "card"
                    ? "bg-sky-50 border-sky-400 text-sky-700 shadow-2xs"
                    : "bg-white border-slate-200 text-slate-600 hover:bg-slate-50"
                }`}
              >
                <CreditCard className="w-4 h-4 text-sky-600" />
                <span>Tarjeta</span>
              </button>

              <button
                type="button"
                onClick={() => setPaymentMethod("transfer")}
                className={`py-2 px-1 rounded-xl border text-[11px] font-bold flex flex-col items-center gap-1 transition-all cursor-pointer ${
                  paymentMethod === "transfer"
                    ? "bg-sky-50 border-sky-400 text-sky-700 shadow-2xs"
                    : "bg-white border-slate-200 text-slate-600 hover:bg-slate-50"
                }`}
              >
                <Building2 className="w-4 h-4 text-sky-600" />
                <span>Transferencia</span>
              </button>
            </div>

            {/* Botón de Cobro */}
            <button
              type="button"
              disabled={cart.length === 0 || !isShiftOpen || isProcessing}
              onClick={handleCheckout}
              className="w-full py-3 bg-[#0284C7] hover:bg-sky-700 active:scale-[0.99] text-white font-bold text-xs rounded-xl shadow-xs transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isProcessing ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Printer className="w-4 h-4" />
              )}
              <span>{isProcessing ? "Procesando Venta..." : "Cobrar & Imprimir Ticket"}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}F